mapper.update:
UPDATE public.trail_edge AS edge SET fwd_ascent_m = value.fwd_ascent_m, fwd_descent_m = value.fwd_descent_m, fwd_uphill_yn = value.fwd_uphill_yn, direction_basis_cd = 'DEM' FROM ( VALUES
( CAST(#{row.edgeId} AS bigint), CAST(#{row.ascentM} AS numeric(7, 1)), CAST(#{row.descentM} AS numeric(7, 1)), CAST(#{row.uphillYn} AS char(1)) )
) AS value(edge_id, fwd_ascent_m, fwd_descent_m, fwd_uphill_yn) WHERE edge.edge_id = value.edge_id AND edge.direction_basis_cd <> 'MANUAL' AND ( edge.direction_basis_cd <> 'DEM' OR edge.fwd_uphill_yn IS NULL OR edge.fwd_ascent_m IS NULL OR edge.fwd_descent_m IS NULL )
